function drawDots(a,b){[a,b].forEach((s,j)=>{const box=$('dots-'+j);if(!box)return;const w=box.clientWidth,h=box.clientHeight;const population=M.journeyCardSample(s.assigned,month,150,scenario.seed),positions=[0,0,0,0],keys=['invited','opened','started','completed'];if(!population.some(p=>p.id===selected)){const target=s.assigned.find(p=>p.id===selected);if(target){if(population.length===150)population.pop();population.push(target)}}for(const p of population){const stage=keys.indexOf(p.history[month].stage),slot=positions[stage]++,cols=Math.max(3,Math.floor((w/4-10)/10));let dot=document.createElement('span');dot.className='dot'+(p.id===selected?' selected':'');dot.style.background=scenario.archetypes[p.type].color;const next={left:(stage*w/4+5+(slot%cols)*((w/4-16)/Math.max(1,cols-1)))+'px',top:(5+Math.floor(slot/cols)*Math.min(10,(h-15)/Math.max(1,Math.ceil(150/cols))))+'px'},key=j+':'+filter+':'+p.id,previous=dotPositions.get(key);Object.assign(dot.style,previous||next);dot.dataset.id=p.id;box.append(dot);if(previous)requestAnimationFrame(()=>requestAnimationFrame(()=>Object.assign(dot.style,next)));dotPositions.set(key,next)}box.onclick=e=>{let best=null,distance=Infinity;for(const dot of box.children){const r=dot.getBoundingClientRect(),v=(r.x+3-e.clientX)**2+(r.y+3-e.clientY)**2;if(v<distance){distance=v;best=dot.dataset.id}}if(best){selected=best;$('person-picker').value=best;document.querySelectorAll('.dot').forEach(el=>el.classList.toggle('selected',el.dataset.id===selected));renderPerson()}}})}
