 document.querySelectorAll('[data-month]').forEach(el=>el.onclick=()=>{stop();month=+el.dataset.month;renderSimulation()});const s=M.summary(result,month,filter),d=aggregateDemand(month);$('workforce-total').textContent=`${M.monthLabel(scenario,month)}: ${s.active.length} active · +${s.joins} / −${s.leavers} to date`;const turnover=M.turnoverRate(result,month,filter);const annual=scenario.departments.filter(d=>filter==='all'||d.id===filter).map(d=>d.name+': '+fmt(d.turnover)+'%').join(' · ');$('turnover-note').textContent='Simulated turnover to date: '+(turnover===null?'—':fmt(turnover)+'%')+' (not annualised). Annual assumptions: '+annual+'.';$('workload-note').textContent=`${M.monthLabel(scenario,month)}: ${fmt(d.required+d.newHours)} h planned demand / ${fmt(d.capacity)} h capacity. ${fmt(d.backlog)} h existing mandatory backlog. Programme demand is remaining hours spread across its completion window; capacity is not guaranteed uptake.`;
