try{document.modelContext?.registerTool({name:'read_learning_simulation',title:'Read Learning Lab scenario results',description:'Read the currently selected month and department, model assumptions and illustrative completion counts. Does not modify data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('This tool accepts an empty object.');let a=M.summary(result,month,filter,0),b=M.summary(result,month,filter,1);return {scenario:scenario.name,month,department:filter,illustrative:true,active:b.active.length,baseline:a.stage,alternative:b.stage,joiners:b.joins,leavers:b.leavers}}})?.catch?.(()=>{});}catch(e){}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(page==='simulation')renderSimulation()},150)});

document.addEventListener('input',e=>{if(e.target.closest('form')){dirty=true;$('save-state').textContent='Unsaved form edits'}});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});

$('attrition-benchmark').onchange=()=>{const b=M.ATTRITION_BENCHMARKS.find(x=>x.id===$('attrition-benchmark').value);if(!b)return;scenario=M.applyAttritionBenchmark(scenario,b.id,filter);recompute();notify(b.name+' benchmark applied: '+b.rate+'% per year, in both plans. Monthly departure overrides, if entered, still take precedence.');};
